const { Worker } = require('node:worker_threads');
const pool = Array.from({ length: os.availableParallelism() },
  () => new Worker(require.resolve('./perform.js')));
let next = 0;
function dispatch(msg) {
  const worker = pool[next++ % pool.length];   // round-robin, exactly one worker
  worker.postMessage(msg);                     // structured clone, no shared state
}
// inline fallback for I/O-bound work (single performer, no parallelism):
